const curso = $('Consulta a la base de datos').item.json;
const embedding = $input.item.json.data[0].embedding;

return {
    json: {
      id: curso.id_curso,
      vector: embedding,
      payload: {
        id_curso: curso.id_curso,
        nombre: curso.nombre,
        descripcion: curso.descripcion,
        categoria: curso.categoria,
        dificultad: curso.dificultad,
        duracion: curso.duracion,
        activo: curso.activo
      }
    }
  }
;

const error = $json.error ?? {};

const mensajeTecnico =
  error.message ??
  error.description ??
  "No se proporcionaron detalles.";

let titulo = "No se pudieron obtener los cursos";
let mensaje = "Ocurrió un problema al consultar la información de los cursos.";
let accion = "Inténtalo nuevamente. Si el problema continúa, contacta al administrador.";

const textoError = mensajeTecnico.toLowerCase();

if (
  textoError.includes("connection") ||
  textoError.includes("connect") ||
  textoError.includes("econnrefused") ||
  textoError.includes("network")
) {
  titulo = "No se pudo conectar con la base de datos";
  mensaje = "No fue posible establecer la conexión con el servicio que almacena la información de los cursos.";
  accion = "Verifica que la base de datos esté disponible e inténtalo nuevamente.";
}

else if (
  textoError.includes("access denied") ||
  textoError.includes("1045") ||
  textoError.includes("unauthorized") ||
  textoError.includes("forbidden")
) {
  titulo = "No se pudo acceder a la base de datos";
  mensaje = "El sistema no tiene autorización para consultar la información de los cursos.";
  accion = "Contacta al administrador del sistema para verificar los permisos de acceso.";
}

else if (
  textoError.includes("unknown database") ||
  textoError.includes("1049") ||
  textoError.includes("database") && textoError.includes("doesn't exist")
) {
  titulo = "No se encontró la base de datos";
  mensaje = "La base de datos que contiene la información de los cursos no está disponible.";
  accion = "Contacta al administrador del sistema para verificar la configuración de la base de datos.";
}

else if (
  textoError.includes("table") &&
  (
    textoError.includes("doesn't exist") ||
    textoError.includes("not found")
  )
) {
  titulo = "No se encontró la información de los cursos";
  mensaje = "La estructura de la base de datos no contiene una de las tablas necesarias para realizar la consulta.";
  accion = "Contacta al administrador del sistema para revisar la estructura de la base de datos.";
}

else if (
  textoError.includes("syntax") ||
  textoError.includes("sql syntax") ||
  textoError.includes("1064")
) {
  titulo = "No se pudo realizar la consulta";
  mensaje = "La consulta utilizada para obtener los cursos contiene un problema y no pudo ejecutarse.";
  accion = "Contacta al administrador del sistema para revisar la consulta.";
}

else if (
  textoError.includes("timeout") ||
  textoError.includes("timed out")
) {
  titulo = "La consulta tardó demasiado";
  mensaje = "La base de datos tardó demasiado en responder y no fue posible obtener los cursos.";
  accion = "Espera unos minutos e inténtalo nuevamente.";
}

else if (
  textoError.includes("server has gone away") ||
  textoError.includes("lost connection")
) {
  titulo = "Se perdió la conexión con la base de datos";
  mensaje = "La conexión con la base de datos se interrumpió mientras se obtenía la información.";
  accion = "Inténtalo nuevamente. Si el problema continúa, contacta al administrador.";
}

return [
  {
    json: {
      estado: "error",
      titulo,
      mensaje,
      curso: null,
      accion_recomendada: accion,
      puede_reintentar: true,
      error_tecnico: mensajeTecnico
    }
  }
];

