const mensajeTecnico =
  error.message ??
  error.description ??
  "No se proporcionaron detalles.";

let titulo = "No se pudo guardar el curso";
let mensaje =
  "Ocurrió un problema al guardar la información del curso en Qdrant.";
let accion =
  "Inténtalo nuevamente. Si el problema continúa, contacta al administrador.";

const textoError = mensajeTecnico.toLowerCase();

if (
  textoError.includes("connection") ||
  textoError.includes("connect") ||
  textoError.includes("econnrefused") ||
  textoError.includes("network")
) {
  titulo = "No se pudo conectar con Qdrant";
  mensaje =
    "No fue posible establecer la conexión con el servicio de Qdrant para guardar la información.";
  accion =
    "Verifica que Qdrant esté disponible e inténtalo nuevamente.";
}

else if (
  textoError.includes("400") ||
  textoError.includes("bad request") ||
  textoError.includes("invalid") ||
  textoError.includes("vector") ||
  textoError.includes("dimension")
) {
  titulo = "Qdrant rechazó el vector";
  mensaje =
    "Qdrant rechazó la información del curso porque los datos enviados no tienen el formato esperado.";
  accion =
    "Verifica el vector y la configuración de la colección.";
}

else if (
  textoError.includes("404") ||
  textoError.includes("not found")
) {
  titulo = "No se encontró la colección";
  mensaje =
    "La colección 'cursos' no está disponible en Qdrant.";
  accion =
    "Verifica que la colección exista antes de guardar los vectores.";
}

else if (
  textoError.includes("401") ||
  textoError.includes("403") ||
  textoError.includes("unauthorized") ||
  textoError.includes("forbidden")
) {
  titulo = "No se pudo acceder a Qdrant";
  mensaje =
    "El sistema no tiene autorización para guardar información en Qdrant.";
  accion =
    "Verifica los permisos y la configuración de acceso a Qdrant.";
}

else if (
  textoError.includes("500") ||
  textoError.includes("502") ||
  textoError.includes("503") ||
  textoError.includes("internal server error") ||
  textoError.includes("service unavailable")
) {
  titulo = "Qdrant no pudo guardar la información";
  mensaje =
    "El servicio de Qdrant presentó un problema interno al guardar el vector.";
  accion =
    "Verifica que Qdrant esté funcionando correctamente e inténtalo nuevamente.";
}

else if (
  textoError.includes("timeout") ||
  textoError.includes("timed out")
) {
  titulo = "Qdrant tardó demasiado en responder";
  mensaje =
    "El servicio de Qdrant no respondió dentro del tiempo esperado.";
  accion =
    "Espera unos minutos e inténtalo nuevamente.";
}

return [
  {
    json: {
      estado: "error",
      titulo,
      mensaje,
      coleccion: "cursos",
      accion_recomendada: accion,
      puede_reintentar: true,
      error_tecnico: mensajeTecnico
    }
  }
];

const error = $json.error ?? {};

const mensajeTecnico =
  error.message ??
  "No se proporcionaron detalles.";

let titulo = "No se pudieron preparar los datos";
let mensaje = "Ocurrió un problema al preparar la información del curso para generar el registro vectorial.";
let accion = "Inténtalo nuevamente. Si el problema continúa, contacta al administrador.";

const textoError = mensajeTecnico.toLowerCase();

if (
  textoError.includes("curso") &&
  (
    textoError.includes("no se encontró") ||
    textoError.includes("no contiene")
  )
) {
  titulo = "No se encontró la información del curso";
  mensaje = "No fue posible obtener los datos necesarios del curso para preparar su información.";
  accion = "Verifica que la consulta a la base de datos esté devolviendo correctamente los cursos.";
}

else if (
  textoError.includes("embedding") &&
  (
    textoError.includes("no se encontró") ||
    textoError.includes("vacío") ||
    textoError.includes("formato")
  )
) {
  titulo = "No se pudo obtener el embedding";
  mensaje = "No fue posible obtener un vector válido para representar la información del curso.";
  accion = "Verifica que el nodo de generación de embeddings esté funcionando correctamente.";
}

else if (
  textoError.includes("dimensiones")
) {
  titulo = "El embedding tiene una dimensión incorrecta";
  mensaje = "El vector generado no tiene la cantidad de dimensiones que espera la colección de Qdrant.";
  accion = "Verifica que el modelo de embeddings utilizado sea compatible con la colección.";
}

else if (
  textoError.includes("id_curso") ||
  textoError.includes("identificador")
) {
  titulo = "El curso no tiene un identificador válido";
  mensaje = "La información recibida del curso no contiene un identificador válido para crear el punto en Qdrant.";
  accion = "Verifica la información devuelta por la base de datos.";
}

return [
  {
    json: {
      estado: "error",
      titulo,
      mensaje,
      curso: null,
      accion_recomendada: accion,
      puede_reintentar: true,
      error_tecnico: mensajeTecnico
    }
  }
];

const error = $json.error ?? {};

const mensajeTecnico =
  error.message ??
  error.description ??
  "No se proporcionaron detalles.";

const nombreCurso =
  $json.nombre ??
  $json.payload?.nombre ??
  "Curso no identificado";

let titulo = "No se pudo generar el embedding";
let mensaje = "Ocurrió un problema mientras se generaba la representación vectorial del curso.";
let accion = "Inténtalo nuevamente. Si el problema continúa, contacta al administrador.";

const textoError = mensajeTecnico.toLowerCase();

if (
  textoError.includes("rate limit") ||
  textoError.includes("too many requests") ||
  textoError.includes("429")
) {
  titulo = "Servicio temporalmente ocupado";
  mensaje = "El servicio de generación de embeddings está temporalmente ocupado y no pudo procesar el curso.";
  accion = "Espera unos minutos y vuelve a intentarlo.";
}

else if (
  textoError.includes("timeout") ||
  textoError.includes("timed out")
) {
  titulo = "La generación del embedding tardó demasiado";
  mensaje = "El servicio tardó demasiado en generar el embedding del curso.";
  accion = "Verifica la conexión e inténtalo nuevamente.";
}

else if (
  textoError.includes("connection") ||
  textoError.includes("connect") ||
  textoError.includes("network") ||
  textoError.includes("econnrefused")
) {
  titulo = "No se pudo conectar con el servicio de embeddings";
  mensaje = "No fue posible comunicarse con el servicio encargado de generar el embedding.";
  accion = "Verifica que el servicio de embeddings esté disponible e inténtalo nuevamente.";
}

else if (
  textoError.includes("400") ||
  textoError.includes("bad request") ||
  textoError.includes("invalid")
) {
  titulo = "No se pudo procesar la información del curso";
  mensaje = "El servicio de embeddings rechazó la información enviada para generar el vector.";
  accion = "Verifica que los datos enviados al servicio tengan el formato esperado.";
}

else if (
  textoError.includes("401") ||
  textoError.includes("403") ||
  textoError.includes("unauthorized") ||
  textoError.includes("forbidden")
) {
  titulo = "No se pudo autorizar la generación del embedding";
  mensaje = "El sistema no tiene autorización para utilizar el servicio de embeddings.";
  accion = "Verifica las credenciales y permisos del servicio de embeddings.";
}

else if (
  textoError.includes("404") ||
  textoError.includes("not found")
) {
  titulo = "No se encontró el servicio de embeddings";
  mensaje = "No fue posible encontrar el modelo o recurso necesario para generar el embedding.";
  accion = "Verifica la configuración del modelo y del servicio de embeddings.";
}

else if (
  textoError.includes("500") ||
  textoError.includes("internal server error") ||
  textoError.includes("502") ||
  textoError.includes("503")
) {
  titulo = "El servicio de embeddings presentó un error";
  mensaje = "El servicio encargado de generar el embedding presentó un problema interno.";
  accion = "Espera unos minutos y vuelve a intentarlo.";
}

return [
  {
    json: {
      estado: "error",
      titulo,
      mensaje,
      curso: nombreCurso,
      accion_recomendada: accion,
      puede_reintentar: true,
      error_tecnico: mensajeTecnico
    }
  }
];

return [
  {
    json: {
      estado: "ok",
      mensaje: "Cursos guardados correctamente."
    }
  }
];
